import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    tokens = data[1:1+n]
    if not tokens or tokens[0] == 'null': print(0); sys.exit(0)
    from collections import deque
    class Node:
        def __init__(self, v): self.v = v; self.left = None; self.right = None
    root = Node(tokens[0])
    q = deque([root])
    idx = 1
    while q and idx < len(tokens):
        curr = q.popleft()
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.left = Node(tokens[idx]); q.append(curr.left)
        idx += 1
        if idx < len(tokens) and tokens[idx] != 'null':
            curr.right = Node(tokens[idx]); q.append(curr.right)
        idx += 1
    def depth(node):
        if not node: return 0
        return 1 + max(depth(node.left), depth(node.right))
    print(depth(root))
else:
    print(0)
